def _collect_prices(prices: Iterable[float]) -> List[float]:
    collected = []
    for price in prices:
        if not isinstance(price, (int, float)):
            raise TypeError("prices must be numeric")
        if price < 0:
            raise ValueError("prices must be non-negative")
        collected.append(float(price))
