    assert expand_ranges([]) == []


def test_negative_and_zero_bounds():
    assert expand_ranges([(-2, 1)]) == [-2, -1, 0, 1]


def test_unsorted_input_is_sorted():
    assert expand_ranges([(10, 11), (0, 1)]) == [0, 1, 10, 11]
